div.script:
document.addEventListener("DOMContentLoaded", function () {
let reserveButtons = document.querySelectorAll(".select-card");

reserveButtons.forEach(button => {
button.addEventListener("click", function () {
document.querySelectorAll(".card-container").forEach(card => {
card.classList.remove("selected-card");
});
let parentCard = this.closest(".card-container");
parentCard.classList.add("selected-card");
let productName = parentCard.querySelector("h5").innerText;
document.getElementById("selectedLane").innerText = productName;
});
});
});

document.addEventListener("DOMContentLoaded", function () {

 let today = new Date().toISOString().split("T")[0];

 document.getElementById("datePicker").setAttribute("min", today);
    document.getElementById("fromDate").setAttribute("min", today);
    document.getElementById("toDate").setAttribute("min", today);

    document.getElementById("fromDate").addEventListener("change", function() {
        document.getElementById("toDate").setAttribute("min", this.value);
                         document.getElementById("datePicker").setAttribute("min", this.value);

    });
    let recurringCheckbox = document.getElementById("recurringBooking");
    let singleDateDiv = document.getElementById("singleDate");
    let recurringDatesDiv = document.getElementById("recurringDates");

    recurringCheckbox.addEventListener("change", function () {
        if (this.checked) {
            singleDateDiv.classList.add("d-none");
            recurringDatesDiv.classList.remove("d-none");
        } else {
            singleDateDiv.classList.remove("d-none");
            recurringDatesDiv.classList.add("d-none");
        }
    });
});

document.addEventListener("DOMContentLoaded", function () {
       let termsCheckbox = document.getElementById("termsCheckbox");
       let confirmBtn = document.getElementById("confirmBtn");
       let warningMessage = document.getElementById("warningMessage");

       function validateBooking() {
           let hasWarning = warningMessage && !warningMessage.classList.contains("d-none"); // Check if warning is visible
           let isTermsChecked = termsCheckbox?.checked || false;

           confirmBtn.disabled = hasWarning || !isTermsChecked;
       }

       if (termsCheckbox) {
           termsCheckbox.addEventListener("change", validateBooking);
       }

       validateBooking();
   });
